set -o pipefail
cd /home/bcorfman/dev/freytag-forge
export TMPDIR=/tmp PYTHONPATH=/home/bcorfman/dev/freytag-forge:/home/bcorfman/dev/freytag-forge/packages/worldkeeper/src
PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
$PY -m ruff check /home/bcorfman/dev/freytag-forge/storygame/story_package/branch_report.py /home/bcorfman/dev/freytag-forge/tests/test_branch_report.py
$PY -m ruff format --check /home/bcorfman/dev/freytag-forge/storygame/story_package/branch_report.py /home/bcorfman/dev/freytag-forge/tests/test_branch_report.py
if grep -n -i -E 'memory_card|kristin|patrol|laptop|k_sl_|t_1a|continuity|pursuit_1b|rebecca|brandon|michelle' /home/bcorfman/dev/freytag-forge/storygame/story_package/branch_report.py; then echo 'STORY NAMES FOUND'; exit 1; fi
if grep -n -i -w 'flag' /home/bcorfman/dev/freytag-forge/storygame/story_package/branch_report.py; then echo 'USE THE WORD RESULT, NOT FLAG'; exit 1; fi
$PY -m pytest /home/bcorfman/dev/freytag-forge/tests/test_branch_report.py /home/bcorfman/dev/freytag-forge/tests/test_gap_rules.py /home/bcorfman/dev/freytag-forge/tests/test_impact_report.py /home/bcorfman/dev/freytag-forge/tests/test_situation_trace.py -q --no-cov -p no:cacheprovider 2>&1 | tail -12
OUT=$($PY /home/bcorfman/dev/freytag-forge/scripts/branch_report.py i_2c_rebecca_corridor) || { echo "script failed"; echo "$OUT"; exit 1; }
n=$(echo "$OUT" | grep -c 'The purge clock was running')
echo "bridge text occurrences in whole report: $n (3 evidence + one per branch handoff expected at most 8)"
test "$n" -le 8 || { echo "BRIDGE TEXT STILL REPEATED"; exit 1; }
echo "$OUT" | grep -q 'through nothing' && { echo "STILL SAYS through nothing"; exit 1; }
echo "$OUT" | grep -q 'Carried over from the branch' || { echo "MISSING carried-over heading"; exit 1; }
echo "$OUT" | grep -q 'Appears with the next scene' || { echo "MISSING appears-with heading"; exit 1; }
echo "$OUT" | grep -q 'combined_broadcast_rescue_plan_known' || { echo "missing exit-read fact"; exit 1; }
echo "$OUT" | sed -n '/^## Comparison/,$p'
